examples.template:
HStack(spacing: theme.spacing.space3) {
    MonarchTextField({{search}}, text: $query, prompt: {{search}}, labelVisibility: .hidden)
        .frame(maxWidth: .infinity)
    HStack(spacing: theme.spacing.space2) {
        MonarchButton({{group.items.0}}, variant: .secondary) {}
        MonarchButton({{group.items.1}}, variant: .secondary) {}
    }
    .accessibilityElement(children: .contain)
    .accessibilityLabel({{group.label}})
    MonarchButton({{end}}, variant: .secondary) {}
        .padding(.leading, theme.spacing.space4)
}
.accessibilityElement(children: .contain)
.accessibilityLabel({{label}})

examples.code:
HStack(spacing: theme.spacing.space3) {
    MonarchTextField("Search tasks", text: $query, prompt: "Search tasks", labelVisibility: .hidden)
        .frame(maxWidth: .infinity)
    HStack(spacing: theme.spacing.space2) {
        MonarchButton("Board", variant: .secondary) {}
        MonarchButton("List", variant: .secondary) {}
    }
    .accessibilityElement(children: .contain)
    .accessibilityLabel("View")
    MonarchButton("Export", variant: .secondary) {}
        .padding(.leading, theme.spacing.space4)
}
.accessibilityElement(children: .contain)
.accessibilityLabel("Task list tools")
